<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { AlertTriangle, ChevronDown, ChevronUp, CircleAlert, RefreshCw, ScrollText, Trash2 } from 'lucide-vue-next';
import ConfirmModal from './ConfirmModal.vue';
import type { DeveloperLogEvent, DeveloperLogType, DeveloperLogsResponse } from '../types';

const events = ref<DeveloperLogEvent[]>([]);
const loading = ref(false); const error = ref(''); const search = ref('');
const type = ref<DeveloperLogType | ''>(''); const severity = ref(''); const from = ref(''); const to = ref('');
const offset = ref(0); const total = ref(0); const hasMore = ref(false); const deletionMode = ref<'soft' | 'hard'>('soft');
const autoRefresh = ref(false); const expanded = ref(new Set<string>()); const clearTarget = ref<DeveloperLogType | 'all' | null>(null); const savingMode = ref(false);
let refreshTimer: ReturnType<typeof setInterval> | null = null; let debounceTimer: ReturnType<typeof setTimeout> | null = null;
const labels: Record<DeveloperLogType, string> = { llm_prompt: 'LLM prompt', exception: 'Exception', router_fallback: 'Router fallback' };

const load = async (append = false) => {
  if (loading.value) return; loading.value = true; error.value = '';
  const query = new URLSearchParams({ offset: String(append ? offset.value : 0), limit: '50' });
  if (search.value.trim()) query.set('search', search.value.trim()); if (type.value) query.set('types', type.value); if (severity.value) query.set('severity', severity.value);
  if (from.value) query.set('start', new Date(from.value).toISOString()); if (to.value) query.set('end', new Date(to.value).toISOString());
  try { const response = await fetch(`/api/logs?${query}`); const data = await response.json() as DeveloperLogsResponse & { detail?: string }; if (!response.ok) throw new Error(data.detail || 'Logs unavailable.');
    events.value = append ? [...events.value, ...data.events] : data.events; total.value = data.total; offset.value = events.value.length; hasMore.value = data.has_more; deletionMode.value = data.deletion_mode || 'soft';
  } catch (cause: any) { error.value = cause?.message || 'Logs unavailable.'; } finally { loading.value = false; }
};
watch([search, type, severity, from, to], () => { if (debounceTimer) clearTimeout(debounceTimer); debounceTimer = setTimeout(() => load(false), 300); });
watch(autoRefresh, (enabled) => { if (refreshTimer) clearInterval(refreshTimer); refreshTimer = enabled ? setInterval(() => load(false), 10000) : null; });
onMounted(() => load()); onBeforeUnmount(() => { if (refreshTimer) clearInterval(refreshTimer); if (debounceTimer) clearTimeout(debounceTimer); });
const toggle = (id: string) => { const next = new Set(expanded.value); next.has(id) ? next.delete(id) : next.add(id); expanded.value = next; };
const clearConfirmed = async () => { if (!clearTarget.value) return; const target = clearTarget.value; const response = await fetch(target === 'all' ? '/api/logs' : `/api/logs/${target}`, { method: 'DELETE' }); if (!response.ok) { error.value = 'Failed to clear logs.'; return; } clearTarget.value = null; await load(false); };
const saveMode = async () => { savingMode.value = true; try { const response = await fetch('/api/logs/config', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ deletion_mode: deletionMode.value }) }); if (!response.ok) throw new Error('Failed to save clear mode.'); } catch (cause: any) { error.value = cause?.message || 'Failed to save clear mode.'; } finally { savingMode.value = false; } };
const formatTime = (value: string) => new Date(value).toLocaleString();
const detailText = (event: DeveloperLogEvent) => event.type === 'llm_prompt' ? event.details.prompt : event.type === 'exception' ? event.details.stackTrace || event.details.message : JSON.stringify(event.details.metadata || {}, null, 2);
const clearMessage = computed(() => `This will ${deletionMode.value === 'hard' ? 'remove the active log and rotated backups' : 'truncate only the active log'}${clearTarget.value === 'all' ? ' for all log types' : ` for ${labels[clearTarget.value as DeveloperLogType]}`}.`);
</script>

<template>
  <div class="flex-1 overflow-y-auto p-6 text-left"><div class="max-w-5xl mx-auto space-y-5">
    <div class="flex flex-wrap items-center justify-between gap-3"><div><h3 class="text-lg font-bold text-white flex items-center gap-2"><ScrollText class="w-5 h-5 text-indigo-400" /> Developer Logs</h3><p class="text-xs text-slate-500 mt-1">{{ total }} matching event(s), newest first.</p></div><div class="flex items-center gap-2"><button @click="load(false)" class="px-3 py-2 rounded-xl border border-slate-700 text-xs text-slate-300 hover:bg-slate-800"><RefreshCw :class="loading ? 'animate-spin' : ''" class="w-3.5 h-3.5 inline mr-1" />Refresh</button><label class="flex items-center gap-2 text-xs text-slate-400"><input v-model="autoRefresh" type="checkbox" /> Auto-refresh</label><button @click="clearTarget = 'all'" class="px-3 py-2 rounded-xl bg-rose-600/90 text-xs text-white hover:bg-rose-500"><Trash2 class="w-3.5 h-3.5 inline mr-1" />Clear all</button></div></div>
    <div class="grid grid-cols-1 md:grid-cols-5 gap-2 rounded-2xl border border-slate-800 bg-slate-900/30 p-4"><input v-model="search" placeholder="Search logs…" class="md:col-span-2 bg-[#11162d] border border-slate-800 rounded-xl px-3 py-2 text-xs text-slate-200" /><select v-model="type" class="bg-[#11162d] border border-slate-800 rounded-xl px-3 py-2 text-xs text-slate-300"><option value="">All types</option><option value="llm_prompt">LLM prompts</option><option value="exception">Exceptions</option><option value="router_fallback">Router fallbacks</option></select><select v-model="severity" class="bg-[#11162d] border border-slate-800 rounded-xl px-3 py-2 text-xs text-slate-300"><option value="">All severity</option><option value="info">Info</option><option value="warning">Warning</option><option value="error">Error</option></select><div class="flex gap-1"><input v-model="from" type="datetime-local" title="From" class="min-w-0 w-1/2 bg-[#11162d] border border-slate-800 rounded-xl px-2 py-2 text-[10px] text-slate-300" /><input v-model="to" type="datetime-local" title="To" class="min-w-0 w-1/2 bg-[#11162d] border border-slate-800 rounded-xl px-2 py-2 text-[10px] text-slate-300" /></div></div>
    <div class="flex flex-wrap items-center justify-between gap-2 text-[10px] text-slate-500"><label class="flex items-center gap-2">Clear mode<select v-model="deletionMode" @change="saveMode" :disabled="savingMode" class="bg-[#11162d] border border-slate-800 rounded-lg px-2 py-1 text-[10px] text-slate-300"><option value="soft">Soft — active file only</option><option value="hard">Hard — active + rotated</option></select></label><span>Hard mode removes rotated exception backups.</span><div class="flex gap-1"><button v-for="(label, key) in labels" :key="key" @click="clearTarget = key" class="px-2 py-1 rounded-lg border border-slate-700 text-slate-400 hover:text-white hover:bg-slate-800">Clear {{ label }}</button></div></div><div v-if="error" class="rounded-xl border border-rose-500/20 bg-rose-500/5 p-3 text-xs text-rose-300"><CircleAlert class="w-4 h-4 inline mr-1" />{{ error }}</div><div v-if="!loading && !events.length" class="rounded-2xl border border-slate-800 p-12 text-center text-xs text-slate-500">No log events match the current filters.</div>
    <div v-else class="space-y-3"><article v-for="event in events" :key="event.id" class="rounded-2xl border border-slate-800 bg-slate-900/30 overflow-hidden"><button @click="toggle(event.id)" class="w-full text-left p-4 flex items-start gap-3 hover:bg-slate-800/20"><span class="mt-0.5 px-2 py-1 rounded-full text-[9px] font-mono" :class="event.type === 'exception' ? 'bg-rose-500/10 text-rose-300' : event.type === 'router_fallback' ? 'bg-amber-500/10 text-amber-300' : 'bg-indigo-500/10 text-indigo-300'">{{ labels[event.type] }}</span><div class="min-w-0 flex-1"><div class="flex justify-between gap-2"><h4 class="text-xs font-semibold text-slate-200">{{ event.title }}</h4><time class="text-[10px] text-slate-500 whitespace-nowrap">{{ formatTime(event.timestamp) }}</time></div><p class="text-xs text-slate-400 mt-1 break-words">{{ event.summary }}</p></div><ChevronUp v-if="expanded.has(event.id)" class="w-4 h-4 text-slate-500" /><ChevronDown v-else class="w-4 h-4 text-slate-500" /></button><div v-if="expanded.has(event.id)" class="border-t border-slate-800 p-4 space-y-3"><div v-if="event.details.query" class="text-xs text-slate-300"><span class="text-slate-500">Query:</span> {{ event.details.query }}</div><pre class="max-h-96 overflow-auto whitespace-pre-wrap rounded-xl bg-[#070a13] border border-slate-800 p-3 text-[11px] leading-relaxed text-slate-300">{{ detailText(event) }}</pre><div v-if="event.details.parserWarning" class="text-[10px] text-amber-300"><AlertTriangle class="w-3 h-3 inline mr-1" />{{ event.details.parserWarning }}</div></div></article><button v-if="hasMore" @click="load(true)" class="w-full py-3 rounded-xl border border-slate-800 text-xs text-slate-400 hover:bg-slate-800/40">Load more</button></div>
  </div></div><ConfirmModal :show="!!clearTarget" title="Clear developer logs?" :message="clearMessage" confirm-label="Clear logs" @confirm="clearConfirmed" @cancel="clearTarget = null" />
</template>
